.dew{position: relative; overflow: hidden; border-radius: 999px; background: linear-gradient(rgba(255, 255, 255, 0.76), rgba(255, 255, 255, 0.5)); border: 1px solid rgba(255, 255, 255, 0.68); box-shadow: rgba(255, 255, 255, 0.72) 0px 1px 0px inset, rgba(255, 255, 255, 0.28) 0px 0px 0px 1px, rgba(97, 218, 251, 0.08) 0px 18px 40px; transition: transform 0.55s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.55s, border-color 0.35s;}
